const dir=fs.mkdtempSync(path.join(os.tmpdir(),'gp11-safe-')),source=path.join(dir,'source.json'),candidate=path.join(dir,'candidate.json'),reportFile=path.join(dir,'report.json');const snapshot=fixtureSnapshot();snapshot.source=sourceFromDocuments(snapshot.documents);fs.writeFileSync(source,JSON.stringify(snapshot));let raw=fs.readFileSync(source,'utf8'),{target,report}=rehearse(raw);assert.deepEqual(report.checks.blockers,[]);fs.writeFileSync(candidate,JSON.stringify(target));fs.writeFileSync(reportFile,JSON.stringify(report));
