assert.equal(run([]).status,0);assert.notEqual(run(['--apply']).status,0);assert.notEqual(spawnSync(process.execPath,['scripts/apply-production-migration.mjs',candidate,'--project','gepuzzellig-test'],{encoding:'utf8'}).status,0);
