const duplicate=structuredClone(snapshot.source);duplicate.profiles.extra={...duplicate.profiles['auth-owner']};assert.throws(()=>rehearse(JSON.stringify(duplicate)),/duplicate-playerId/);
const mismatched=structuredClone(snapshot.source);mismatched.profiles['auth-owner'].authUid='somebody-else';assert.throws(()=>rehearse(JSON.stringify(mismatched)),/authUid-mismatch/);
