const readinessFile=path.join(dir,'readiness.json'),runtimeBackups={};for(const name of ['client','rules','functions','authConfig']){const file=name+'.backup';fs.writeFileSync(path.join(dir,file),'synthetic '+name);runtimeBackups[name]={file,sha256:hash(fs.readFileSync(path.join(dir,file)))}}const readiness={version:1,freezeConfirmed:true,preClient:true,freezeStartedAt:snapshot.capturedAt,releaseCommit:report.releaseCommit,sourceSha256:hash(raw),runtimeBackups};fs.writeFileSync(readinessFile,JSON.stringify(readiness));validateReadiness(readinessFile,ready.provenance);fs.writeFileSync(path.join(dir,'rules.backup'),'tamper');assert.throws(()=>validateReadiness(readinessFile,ready.provenance),/hash/);
