for(let i=0;i<240;i++)target.progress.p_owner['extra'+i]={...Object.values(target.progress.p_owner)[0],puzzleKey:'free-'+i};const documents=planDocuments(target),db=new MemoryFirestore(snapshot.documents),journalFile=path.join(dir,'journal.json'),options={snapshot,documents,provenance:{...ready.provenance,candidateSha256:hash(target)},journalFile,types};
