await executeMigration(db,options);const complete=await readDocuments(db);await executeMigration(db,options);assert(same(complete,await readDocuments(db)),'retry is idempotent');const restored=await executeMigration(db,{...options,rollback:true});assert.equal(restored.baselineRestored,true);assert(same(await readDocuments(db),snapshot.documents),'full baseline restored, including profiles and absence of new documents');
