const db3=new MemoryFirestore(snapshot.documents),journal3=path.join(dir,'journal3.json'),o3={...options,journalFile:journal3};await executeMigration(db3,o3);assert.equal(spawnSync(process.execPath,['scripts/mark-migration-client-active.mjs',journal3,'--confirm-release',report.releaseCommit],{encoding:'utf8'}).status,0);await assert.rejects(executeMigration(db3,{...o3,rollback:true}),/clientactivatie/);
