const auth={listUsers:async()=>({users:snapshot.authUsers.map(x=>({toJSON:()=>x}))})};await assertAuthUnchanged(auth,snapshot.authUsers);await assert.rejects(assertAuthUnchanged(auth,[...snapshot.authUsers,{uid:'new-auth'}]),/Auth-identiteiten/);
